11	// Author: Gu, Zihan
12	// Description:
13	`timescale 1ns/1ns
14	//`include "IDecode_define.v"
15	`include "define.v"
16	
17	module  csrexe(
18	  input                                       clk                             ,
19	  input                                       rst_n                           ,
20	
21	  //control signal
22	  input   [31:0]                              ctrl_inst_i                     ,
23	  input   [1:0]                               ctrl_csr_i                      ,
24	  input                                       ctrl_custom_signal_0_i          ,
25	  input                                       ctrl_isvec_i                    ,
26	  input   [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]   ctrl_reg_idxw_i                 ,
27	  input                                       ctrl_wxd_i                      ,
28	  input   [`DEPTH_WARP-1:0]                   ctrl_wid_i                      ,
29	  //input   [`XLEN-1:0]                         ctrl_spike_info_pc_i            ,
30	  //input   [31:0]                              ctrl_spike_info_inst_i          ,
31	
32	  input                                       in_valid_i                      ,
33	  input                                       out_ready_i                     ,
34	
35	  input   [`XLEN-1:0]                         in1_i                           ,
36	  input   [`DEPTH_WARP*3-1:0]                 rm_wid_i                        ,
37	  input   [`DEPTH_WARP-1:0]                   lsu_wid_i                       ,
38	  input   [`DEPTH_WARP-1:0]                   simt_wid_i                      ,
39	
40	  //CTA2csr
41	  input                                       CTA2csr_valid_i                 ,
42	  input   [`WF_COUNT_WIDTH-1:0]               dispatch2cu_wg_wf_count_i       ,
43	  input   [`WAVE_ITEM_WIDTH-1:0]              dispatch2cu_wf_size_dispatch_i  ,
44	  input   [`SGPR_ID_WIDTH:0]                  dispatch2cu_sgpr_base_dispatch_i,
45	  input   [`VGPR_ID_WIDTH:0]                  dispatch2cu_vgpr_base_dispatch_i,
46	  input   [`TAG_WIDTH-1:0]                    dispatch2cu_wf_tag_dispatch_i   ,
47	  input   [`LDS_ID_WIDTH:0]                   dispatch2cu_lds_base_dispatch_i ,
48	  //input   [`MEM_ADDR_WIDTH-1:0]               dispatch2cu_start_pc_dispatch_i ,
49	  input   [`MEM_ADDR_WIDTH-1:0]               dispatch2cu_pds_base_dispatch_i ,
50	  //input   [`MEM_ADDR_WIDTH-1:0]               dispatch2cu_gds_base_dispatch_i ,
51	  input   [`MEM_ADDR_WIDTH-1:0]               dispatch2cu_csr_knl_dispatch_i  ,
52	  input   [`WG_SIZE_X_WIDTH-1:0]              dispatch2cu_wgid_x_dispatch_i   ,
53	  input   [`WG_SIZE_Y_WIDTH-1:0]              dispatch2cu_wgid_y_dispatch_i   ,
54	  input   [`WG_SIZE_Z_WIDTH-1:0]              dispatch2cu_wgid_z_dispatch_i   ,
55	  input   [31:0]                              dispatch2cu_wg_id_i             ,
56	  input   [`DEPTH_WARP-1:0]                   wid_i                           ,
57	
58	  output                                      in_ready_o                      ,
59	  output                                      out_valid_o                     ,
60	
61	  output  [`XLEN-1:0]                         wb_wxd_rd_o                     ,
62	  output                                      wxd_o                           ,
63	  output  [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]   reg_idxw_o                      ,
64	  output  [`DEPTH_WARP-1:0]                   warp_id_o                       ,
65	  //output  [`XLEN-1:0]                         spike_info_pc_o                 ,
66	  //output  [31:0]                              spike_info_inst_o               ,
67	  output  [8:0]                               rm_o                            ,
68	  output  [`NUM_WARP*(`SGPR_ID_WIDTH+1)-1:0]  sgpr_base_o                     ,
69	  output  [`NUM_WARP*(`VGPR_ID_WIDTH+1)-1:0]  vgpr_base_o                     ,
70	  output  [`XLEN-1:0]                         lsu_tid_o                       ,
71	  output  [`XLEN-1:0]                         lsu_pds_o                       ,
72	  output  [`XLEN-1:0]                         lsu_numw_o                      ,
73	  output  [`XLEN-1:0]                         simt_rpc_o                      
74	  );
75	  
76	  wire   [31:0]                  ctrl_inst                                               ; 
77	  wire   [1:0]                   ctrl_csr                                                ; 
78	  wire                           ctrl_custom_signal_0                                    ; 
79	  wire                           ctrl_isvec                                              ; 
80	  wire   [`XLEN-1:0]             in1                                                     ; 
81	  wire                           write                            [0:`NUM_WARP-1]        ;
82	
83	  wire                           CTA2csr_valid                    [0:`NUM_WARP-1]        ;
84	  wire   [`WF_COUNT_WIDTH-1:0]   dispatch2cu_wg_wf_count                                 ;
85	  wire   [`WAVE_ITEM_WIDTH-1:0]  dispatch2cu_wf_size_dispatch                            ;
86	  wire   [`SGPR_ID_WIDTH:0]      dispatch2cu_sgpr_base_dispatch                          ;
87	  wire   [`VGPR_ID_WIDTH:0]      dispatch2cu_vgpr_base_dispatch                          ;
88	  wire   [`TAG_WIDTH-1:0]        dispatch2cu_wf_tag_dispatch                             ;
89	  wire   [`LDS_ID_WIDTH:0]       dispatch2cu_lds_base_dispatch                           ;
90	  //wire   [`MEM_ADDR_WIDTH-1:0]   dispatch2cu_start_pc_dispatch                           ;
91	  wire   [`MEM_ADDR_WIDTH-1:0]   dispatch2cu_pds_base_dispatch                           ;
92	  //wire   [`MEM_ADDR_WIDTH-1:0]   dispatch2cu_gds_base_dispatch                           ;
93	  wire   [`MEM_ADDR_WIDTH-1:0]   dispatch2cu_csr_knl_dispatch                            ;
94	  wire   [`WG_SIZE_X_WIDTH-1:0]  dispatch2cu_wgid_x_dispatch                             ;
95	  wire   [`WG_SIZE_Y_WIDTH-1:0]  dispatch2cu_wgid_y_dispatch                             ;
96	  wire   [`WG_SIZE_Z_WIDTH-1:0]  dispatch2cu_wgid_z_dispatch                             ;
97	  wire   [31:0]                  dispatch2cu_wg_id                                       ;
98	  wire   [`DEPTH_WARP-1:0]       wid                                                     ;
99	  
100	  wire   [`XLEN-1:0]             wb_wxd_rd                        [0:`NUM_WARP-1]        ;
101	  wire   [2:0]                   frm                              [0:`NUM_WARP-1]        ;
102	  wire   [`SGPR_ID_WIDTH:0]      sgpr_base                        [0:`NUM_WARP-1]        ;
103	  wire   [`VGPR_ID_WIDTH:0]      vgpr_base                        [0:`NUM_WARP-1]        ;
104	  wire   [`XLEN-1:0]             simt_rpc                         [0:`NUM_WARP-1]        ;
105	  wire   [`XLEN-1:0]             lsu_tid                          [0:`NUM_WARP-1]        ;
106	  wire   [`XLEN-1:0]             lsu_pds                          [0:`NUM_WARP-1]        ;
107	  wire   [`XLEN-1:0]             lsu_numw                         [0:`NUM_WARP-1]        ;
108	  
109	  //fifo输入数据
110	  wire   [`XLEN+1+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP-1:0] fifo_data_in                  ;
111	  wire   [`XLEN+1+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP-1:0] fifo_data_out                 ;
112	  wire                                                         fifo_in_valid                 ;
113	  wire                                                         fifo_in_ready                 ;
114	  wire                                                         fifo_out_valid                ;
115	  wire                                                         fifo_out_ready                ;
116	  
117	  genvar  i;
118	  generate  
119	    for(i=0;i<`NUM_WARP;i=i+1) begin : B1//将csrfile例化num_warp次
120	      csrfile U_vcsr_i (
121	                           .clk                             (clk                           ), 
122	                           .rst_n                           (rst_n                         ), 
123	                                                                                           
124	                                                                                           
125	                           .ctrl_inst_i                     (ctrl_inst                     ), 
126	                           .ctrl_csr_i                      (ctrl_csr                      ),
127	                           .ctrl_custom_signal_0_i          (ctrl_custom_signal_0          ),
128	                           .ctrl_isvec_i                    (ctrl_isvec                    ),
129	                                                                                           
130	                           .in1_i                           (in1                           ),
131	                           .write_i                         (write[i]                      ),
132	                                                                                           
133	                                                                                           
134	                           .CTA2csr_valid_i                 (CTA2csr_valid[i]              ),
135	                           .dispatch2cu_wg_wf_count_i       (dispatch2cu_wg_wf_count       ),
136	                           .dispatch2cu_wf_size_dispatch_i  (dispatch2cu_wf_size_dispatch  ),
137	                           .dispatch2cu_sgpr_base_dispatch_i(dispatch2cu_sgpr_base_dispatch),
138	                           .dispatch2cu_vgpr_base_dispatch_i(dispatch2cu_vgpr_base_dispatch),
139	                           .dispatch2cu_wf_tag_dispatch_i   (dispatch2cu_wf_tag_dispatch   ),
140	                           .dispatch2cu_lds_base_dispatch_i (dispatch2cu_lds_base_dispatch ),
141	                           //.dispatch2cu_start_pc_dispatch_i (dispatch2cu_start_pc_dispatch ),
142	                           .dispatch2cu_pds_base_dispatch_i (dispatch2cu_pds_base_dispatch ),
143	                           //.dispatch2cu_gds_base_dispatch_i (dispatch2cu_gds_base_dispatch ),
144	                           .dispatch2cu_csr_knl_dispatch_i  (dispatch2cu_csr_knl_dispatch  ),
145	                           .dispatch2cu_wgid_x_dispatch_i   (dispatch2cu_wgid_x_dispatch   ),
146	                           .dispatch2cu_wgid_y_dispatch_i   (dispatch2cu_wgid_y_dispatch   ),
147	                           .dispatch2cu_wgid_z_dispatch_i   (dispatch2cu_wgid_z_dispatch   ),
148	                           .dispatch2cu_wg_id_i             (dispatch2cu_wg_id             ),
149	                           //.wid_i                           (wid                           ),
150	                                                                                           
151	                           .wb_wxd_rd_o                     (wb_wxd_rd[i]                  ),
152	                           .frm_o                           (frm[i]                        ),
153	                           .sgpr_base_o                     (sgpr_base[i]                  ),
154	                           .vgpr_base_o                     (vgpr_base[i]                  ),
155	                           .simt_rpc_o                      (simt_rpc[i]                   ),
156	                           .lsu_tid_o                       (lsu_tid[i]                    ),
157	                           .lsu_pds_o                       (lsu_pds[i]                    ),
158	                           .lsu_numw_o                      (lsu_numw[i]                   )
159	                       );
160	
161	        //将选中的csr寄存器的输入使能拉高
162	        assign  write[i] = (i == ctrl_wid_i) ? (in_valid_i & in_ready_o) : 1'b0;
163	        assign  CTA2csr_valid[i] = (i == wid) ? CTA2csr_valid_i : 1'b0         ;
164	       
165	        //输出赋值
166	        assign  vgpr_base_o[((i+1)*(`VGPR_ID_WIDTH+1)-1)-:`VGPR_ID_WIDTH+1]  = vgpr_base[i];
167	        assign  sgpr_base_o[((i+1)*(`SGPR_ID_WIDTH+1)-1)-:`SGPR_ID_WIDTH+1]  = sgpr_base[i]; 
168	        //assign  rm_o[((i+1)*3-1)-:3] = frm[i];
169	    end
170	    endgenerate
171	
172	    //ctrl赋值
173	    assign  ctrl_inst            = ctrl_inst_i;
174	    assign  ctrl_csr             = ctrl_csr_i;
175	    assign  ctrl_custom_signal_0 = ctrl_custom_signal_0_i;
176	    assign  ctrl_isvec           = ctrl_isvec_i;
177	    assign  in1                  = in1_i;
178	    //CTA2csr赋值
179	    assign  dispatch2cu_wg_wf_count         = dispatch2cu_wg_wf_count_i       ;
180	    assign  dispatch2cu_wf_size_dispatch    = dispatch2cu_wf_size_dispatch_i  ;
181	    assign  dispatch2cu_sgpr_base_dispatch  = dispatch2cu_sgpr_base_dispatch_i;
182	    assign  dispatch2cu_vgpr_base_dispatch  = dispatch2cu_vgpr_base_dispatch_i;
183	    assign  dispatch2cu_wf_tag_dispatch     = dispatch2cu_wf_tag_dispatch_i   ;
184	    assign  dispatch2cu_lds_base_dispatch   = dispatch2cu_lds_base_dispatch_i ;
185	    //assign  dispatch2cu_start_pc_dispatch   = dispatch2cu_start_pc_dispatch_i ;
186	    assign  dispatch2cu_pds_base_dispatch   = dispatch2cu_pds_base_dispatch_i ;
187	    //assign  dispatch2cu_gds_base_dispatch   = dispatch2cu_gds_base_dispatch_i ;
188	    assign  dispatch2cu_csr_knl_dispatch    = dispatch2cu_csr_knl_dispatch_i  ; 
189	    assign  dispatch2cu_wgid_x_dispatch     = dispatch2cu_wgid_x_dispatch_i   ;  
190	    assign  dispatch2cu_wgid_y_dispatch     = dispatch2cu_wgid_y_dispatch_i   ;  
191	    assign  dispatch2cu_wgid_z_dispatch     = dispatch2cu_wgid_z_dispatch_i   ;  
192	    assign  dispatch2cu_wg_id               = dispatch2cu_wg_id_i             ;            
193	    assign  wid                             = wid_i                           ;
194	
195	    genvar  j;
196	    generate
197	      for(j=0;j<3;j=j+1) begin : B2
198	        assign rm_o[((j+1)*3-1)-:3] = frm[rm_wid_i[((j+1)*`DEPTH_WARP-1)-:`DEPTH_WARP]];  
199	      end
200	    endgenerate
201	
202	    assign  lsu_tid_o  = lsu_tid[lsu_wid_i]  ;
203	    assign  lsu_pds_o  = lsu_pds[lsu_wid_i]  ;
204	    assign  lsu_numw_o = lsu_numw[lsu_wid_i] ;
205	    assign  simt_rpc_o = simt_rpc[simt_wid_i];
206	    //fifo输入数据
207	    assign  fifo_data_in   = {ctrl_reg_idxw_i,ctrl_wxd_i,wb_wxd_rd[ctrl_wid_i],ctrl_wid_i} ;
208	    assign  fifo_in_valid  = in_valid_i & in_ready_o                                       ;
209	    assign  fifo_out_ready = out_ready_i                                                   ;
210	    //fifo输出数据
211	    assign  out_valid_o    = fifo_out_valid                                                ;
212	    assign  in_ready_o     = fifo_in_ready & (~CTA2csr_valid_i)                            ;
213	    assign  reg_idxw_o     = fifo_data_out[`XLEN+1+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP-1:`XLEN+1+`DEPTH_WARP];
214	    assign  wxd_o          = fifo_data_out[`XLEN+`DEPTH_WARP]                                                    ;
215	    assign  wb_wxd_rd_o    = fifo_data_out[`XLEN+`DEPTH_WARP-1:`DEPTH_WARP]                                      ;
216	    assign  warp_id_o      = fifo_data_out[`DEPTH_WARP-1:0]                                                      ;
217	    //例化fifo
218	    stream_fifo_pipe_true #(.DATA_WIDTH(`XLEN+1+`REGIDX_WIDTH+`REGEXT_WIDTH+`DEPTH_WARP),
219	                            .FIFO_DEPTH(1)
220	    ) U_fifo(
221	              .clk        (clk           ),
222	              .rst_n      (rst_n         ),
223	              .w_valid_i  (fifo_in_valid ),
224	              .w_data_i   (fifo_data_in  ),
225	              .r_ready_i  (fifo_out_ready),
226	
227	              .w_ready_o  (fifo_in_ready ),
228	              .r_data_o   (fifo_data_out ),
229	              .r_valid_o  (fifo_out_valid)
230	            );
231	endmodule    
